// Generated by the mutation-kill run on the fee module. Every expected value
// below was re-derived by hand from docs/specs/card-fees.md and checked by
// the billing owner in the PR review before merge; each assertion names the
// spec rule it comes from.

import { describe, it, expect } from "vitest";
import { calculateFee, validateAmount, applyDiscount } from "../src/fees.js";

describe("card fees", () => {
  it("charges 2.9% plus 30 cents on a domestic card", () => {
    // card-fees.md rule F1: fee = round(amount * 0.029) + 30 (amounts in cents).
    // 10000 * 0.029 = 290, + 30 = 320.
    expect(calculateFee(10000, "domestic")).toBe(320);
  });

  it("charges 4.4% plus 30 cents on an international card", () => {
    // card-fees.md rule F2: fee = round(amount * 0.044) + 30.
    // 10000 * 0.044 = 440, + 30 = 470.
    expect(calculateFee(10000, "international")).toBe(470);
  });

  it("rounds a half-cent fee up", () => {
    // card-fees.md rule F3: round half up. 1500 * 0.029 = 43.5 -> 44, + 30 = 74.
    expect(calculateFee(1500, "domestic")).toBe(74);
  });

  it("rejects an amount above the 999,999.99 single-charge ceiling", () => {
    // card-fees.md rule L1: the processor contract caps one charge at 99999999 cents.
    expect(validateAmount(99999999)).toBe(true);
    expect(validateAmount(100000000)).toBe(false);
  });

  it("gives GOLD customers 15% off the order total", () => {
    // card-fees.md rule D2: GOLD tier = 15% off. 500 * 0.85 = 425.
    expect(applyDiscount(500, "GOLD")).toBe(425);
  });
});
